  byKindModel: SpendBreakdownView[];
  conflictRuns: SpendBreakdownView[];
  byReviewRound: SpendBreakdownView[];
  bySession: SpendBreakdownView[];
  byCheckpoint: SpendBreakdownView[];
  bySubagents: SubagentBreakdownView[];
