/**
 * Stage is where a task stands, in the terms of the GitLab board.
 */
/**
 * StagePending: nothing ran yet and no run is requested.
 */
export const StagePending = "pending";
/**
 * StageWorking: a run is requested or in progress.
 */
export const StageWorking = "working";
/**
 * StageWaiting: a run is requested but waits for capacity or for a
 * usage limit to reset.
 */
export const StageWaiting = "waiting";
/**
 * StageNeedsInput: the agent has questions, or CI is still red after the
 * fix rounds.
 */
export const StageNeedsInput = "needs-input";
/**
 * StageCI: the pipeline of the agent's push runs or is being fixed.
 */
export const StageCI = "ci";
/**
 * StageReview: the merge request waits for a human.
 */
export const StageReview = "review";
/**
 * StagePlanned: the spec agent planned the milestone.
 */
export const StagePlanned = "planned";
/**
 * StageFailed: the last run failed.
 */
export const StageFailed = "failed";
/**
 * StageBlocked: the task hit a safety limit.
 */
export const StageBlocked = "blocked";
export type Stage = typeof StagePending | typeof StageWorking | typeof StageWaiting | typeof StageNeedsInput | typeof StageCI | typeof StageReview | typeof StagePlanned | typeof StageFailed | typeof StageBlocked;
/**
 * GitLabRef points to the project in GitLab.
 */
export interface GitLabRef {
  url: string;
  project: string;
  webURL: string;
}
/**
 * ProjectSummary is an AgentProject with counts over its tasks.
 */
export interface ProjectSummary extends Cost {
  namespace: string;
  name: string;
  gitlab: GitLabRef;
  suspend: boolean;
  maxConcurrentRuns: number /* int32 */;
  pollInterval: string;
  lastSyncTime?: string;
  usageLimits?: aiv1.UsageLimit[];
  engineUsage?: aiv1.EngineUsage[];
  conditions?: aiv1.Condition[];
  tasks: number /* int */;
  stages: { [key in Stage]?: number };
  createdAt: string;
  autopilots?: AutopilotOverview[];
}
/**
 * AutopilotOverview is the state of one autopilot milestone.
 */
export interface AutopilotOverview {
  milestoneIID: number /* int64 */;
  title: string;
  phase: aiv1.AutopilotPhase;
  pausedReason?: string;
  /**
   * WaitingFor is the issue a paused autopilot waits for: a run is working
   * on it, and autopilot continues by itself once it passes the gate.
   */
  waitingFor?: number /* int64 */;
  done: number /* int */;
  total: number /* int */;
}
/**
 * ProjectDetail is a project with its tasks grouped by milestone.
 */
export interface ProjectDetail extends ProjectSummary {
  /**
   * Milestones, newest first.
   */
  milestones: Milestone[];
  /**
   * Unplanned are tasks of issues without a milestone.
   */
  unplanned: Task[];
}
/**
 * Milestone groups the tasks of one milestone.
 */
export interface Milestone extends Cost {
  id: number /* int64 */;
  iid: number /* int64 */;
  title: string;
  webURL: string;
  /**
   * Spec is the milestone's spec task, if it is planned by the agent.
   */
  spec?: Task;
  /**
   * TrackingIssueIID is the milestone's tracking issue (its chat), 0
   * without one.
   */
  trackingIssueIID?: number /* int64 */;
  /**
   * Tasks are the implement tasks, by issue IID.
   */
  tasks: Task[];
}
/**
 * Task is an AgentTask.
 */
export interface Task {
  namespace: string;
  name: string;
  project: string;
  type: aiv1.TaskType;
  milestone?: aiv1.MilestoneRef;
  issue?: aiv1.IssueRef;
  suspend: boolean;
  autopilot: boolean;
  runRequest: number /* int64 */;
  runPending: boolean;
  stage: Stage;
  createdAt: string;
  status: aiv1.AgentTaskStatus;
  /**
   * Companion is the issue's companion merge request, with the landing
   * state of the project's status once the home change is merged; the
   * issue and merge request cards show it as a chip.
   */
  companion?: CompanionView;
}
